// ── Infrastructure asset model ──────────────────────────────────────────────
// BOOTSTRAP-ONLY data. The live source of truth is now the snapshot.json
// shipped with each build, NOT this file. This array is consumed by
// migrateInfrastructure() exactly ONCE per fresh browser to seed empty
// localStorage. Once any sub-map has assets in localStorage, this file is
// never read again (the migration short-circuits — see the safety net in
// data/migrateInfrastructure.ts).
//
// DO NOT edit this file to update the live map. Edit the snapshot via the
// running app (which writes localStorage), then export via the build pipeline.
// Editing this file ONLY affects the cold-start seed for visitors with no
// existing data — a code change here is invisible to any returning visitor.
//
// Each asset belongs to exactly one sub-map. The sub-map is where the asset is
// placed and edited; the overview map *projects* these assets into each
// sub-map's calibrated region box (see data/submapRegions.ts) so an asset is
// defined once and shown in both views.
//
// Naming / IDs are standardised and global per type — Transformer 1..N and
// MPAN 1..N run as one unbroken sequence across the whole campus, regardless
// of sub-map. IDs are structured and stable (`transformer-07`) so cables,
// panels, energy data and future backend records can reference an asset by a
// permanent key rather than by its (editable) display name.
//
// Batteries are deliberately NOT in this model yet — they remain a temporary
// overview-only layer until they are placed properly on the sub-maps.
//
// Positions (x, y) are percentages of the SUB-MAP canvas and stay editable
// in-app. Assets migrated from the old overview layer are parked in a grid on
// the left edge of their new sub-map, ready to be dragged into place.

import type { AssetType } from './assets';

// Parent sub-map ids — must match the ids in data/submaps.ts.
export type SubMapId = 'etihad-stadium-map' | 'cfa-map' | 'co-op-live-map';

export interface InfrastructureAsset {
  /** Structured, permanent, unique id — e.g. 'transformer-07'. */
  id: string;
  /** Display name — e.g. 'Transformer 7'. Editable; never used as a key. */
  name: string;
  /** Asset type — drives the marker icon / colour (see data/assetTypes.ts). */
  type: AssetType;
  /** The sub-map this asset belongs to — its single home. */
  subMapId: SubMapId;
  /** Parent site label. Currently mirrors the sub-map's site. */
  site: string;
  /** Position as a percentage of the sub-map canvas. Editable in-app. */
  x: number;
  y: number;
  /** Real MPAN number, where known (MPAN assets only). */
  mpan?: string;
  /** Free-text notes. */
  notes?: string;
  /** Extensible metadata bag — make, rating, etc. Backend-ready. */
  metadata?: Record<string, string>;
  /** Reserved — link to an energy dataset by id (not by name). */
  energyKey?: string;
  /** Reserved — link to a future half-hourly dataset by id. */
  hhDataKey?: string;
}

