/** Every infrastructure asset belonging to a given sub-map. */
export function infrastructureForSubMap(subMapId: string): InfrastructureAsset[] {
  return infrastructure.filter((a) => a.subMapId === subMapId);
}

/** Look up a single infrastructure asset by its permanent id. */
export function infrastructureById(id: string): InfrastructureAsset | undefined {
  return infrastructure.find((a) => a.id === id);
}
